class MovementConfirmationMethod(str, Enum):
    NFC = "NFC"
    DYNAMIC_QR = "DYNAMIC_QR"
    SECURE_PORTAL = "SECURE_PORTAL"
    SECURE_LINK = "SECURE_LINK"


class MovementConfirmationStatus(str, Enum):
    PENDIENTE = "PENDIENTE"
    ACEPTADO = "ACEPTADO"
    DISPUTADO = "DISPUTADO"
    RESUELTO = "RESUELTO"


class MovementResolutionKind(str, Enum):
    CONFIRMAR_ORIGINAL = "CONFIRMAR_ORIGINAL"
    AJUSTE_AUTORIZADO = "AJUSTE_AUTORIZADO"
    RECHAZAR_RECLAMO = "RECHAZAR_RECLAMO"


@dataclass(frozen=True)
class MovementConfirmation:
    confirmation_id: str
    event_id: str
    assignment_id: str
    status: MovementConfirmationStatus
    method: MovementConfirmationMethod
    requested_confirmer_membership_id: Optional[str] = None
    confirmer_membership_id: Optional[str] = None
    evidence_reference: Optional[str] = None
    dispute_reason: Optional[str] = None
    resolution_kind: Optional[MovementResolutionKind] = None
    resolution_reason: Optional[str] = None
    adjustment_event_id: Optional[str] = None


def validate_movement_confirmation(confirmation: MovementConfirmation) -> None:
    for field_name, value in (
        ("confirmation_id", confirmation.confirmation_id),
        ("event_id", confirmation.event_id),
        ("assignment_id", confirmation.assignment_id),
    ):
        if not str(value or "").strip():
            raise ValueError(f"MovementConfirmation requiere {field_name}")

    if confirmation.status == MovementConfirmationStatus.PENDIENTE:
        if confirmation.resolution_kind is not None or confirmation.adjustment_event_id is not None:
            raise ValueError("PENDIENTE no puede tener resolución ni ajuste")
        return

    if confirmation.status == MovementConfirmationStatus.ACEPTADO:
        if not str(confirmation.confirmer_membership_id or "").strip():
            raise ValueError("ACEPTADO requiere confirmer_membership_id")
        if not str(confirmation.evidence_reference or "").strip():
            raise ValueError("ACEPTADO requiere evidence_reference")
        if confirmation.resolution_kind is not None or confirmation.adjustment_event_id is not None:
            raise ValueError("ACEPTADO no debe contener resolución de disputa")
        return

    if confirmation.status == MovementConfirmationStatus.DISPUTADO:
        if not str(confirmation.confirmer_membership_id or "").strip():
            raise ValueError("DISPUTADO requiere confirmer_membership_id")
        if not str(confirmation.dispute_reason or "").strip():
            raise ValueError("DISPUTADO requiere dispute_reason")
        if confirmation.resolution_kind is not None or confirmation.adjustment_event_id is not None:
            raise ValueError("DISPUTADO aún no puede tener resolución")
        return

    if confirmation.status == MovementConfirmationStatus.RESUELTO:
        if confirmation.resolution_kind is None:
            raise ValueError("RESUELTO requiere resolution_kind")
        if not str(confirmation.resolution_reason or "").strip():
            raise ValueError("RESUELTO requiere resolution_reason")
        if confirmation.resolution_kind == MovementResolutionKind.AJUSTE_AUTORIZADO:
            if not str(confirmation.adjustment_event_id or "").strip():
                raise ValueError("AJUSTE_AUTORIZADO requiere adjustment_event_id nuevo")
            if confirmation.adjustment_event_id == confirmation.event_id:
                raise ValueError("El ajuste no puede reescribir el evento original")
        elif confirmation.adjustment_event_id is not None:
            raise ValueError("Solo AJUSTE_AUTORIZADO puede incluir adjustment_event_id")
        return

    raise ValueError("Estado de confirmación no soportado")

import pytest

from modules.cava_socios.domain import (
    MovementConfirmation,
    MovementConfirmationMethod,
    MovementConfirmationStatus,
    MovementResolutionKind,
    validate_movement_confirmation,
)


def _confirmation(status, **kwargs):
    data = dict(
        confirmation_id="CONF-1",
        event_id="EV-1",
        assignment_id="ASG-1",
        status=status,
        method=MovementConfirmationMethod.SECURE_PORTAL,
    )
    data.update(kwargs)
    return MovementConfirmation(**data)


def test_supported_confirmation_methods_are_provider_neutral():
    assert {item.value for item in MovementConfirmationMethod} == {
        "NFC", "DYNAMIC_QR", "SECURE_PORTAL", "SECURE_LINK"
    }


def test_pending_confirmation_does_not_fake_acceptance():
    validate_movement_confirmation(_confirmation(MovementConfirmationStatus.PENDIENTE))


def test_acceptance_requires_real_confirmer_and_evidence():
    with pytest.raises(ValueError):
        validate_movement_confirmation(_confirmation(MovementConfirmationStatus.ACEPTADO))
    validate_movement_confirmation(_confirmation(
        MovementConfirmationStatus.ACEPTADO,
        confirmer_membership_id="MEM-1",
        evidence_reference="EVID-1",
    ))


def test_dispute_requires_reason_and_preserves_original_event():
    validate_movement_confirmation(_confirmation(
        MovementConfirmationStatus.DISPUTADO,
        confirmer_membership_id="MEM-1",
        dispute_reason="Saldo no reconocido",
    ))


def test_authorized_adjustment_creates_new_event_instead_of_mutating_original():
    with pytest.raises(ValueError):
        validate_movement_confirmation(_confirmation(
            MovementConfirmationStatus.RESUELTO,
            resolution_kind=MovementResolutionKind.AJUSTE_AUTORIZADO,
            resolution_reason="Inventario físico validado",
            adjustment_event_id="EV-1",
        ))
    validate_movement_confirmation(_confirmation(
        MovementConfirmationStatus.RESUELTO,
        resolution_kind=MovementResolutionKind.AJUSTE_AUTORIZADO,
        resolution_reason="Inventario físico validado",
        adjustment_event_id="EV-2",
    ))


def test_confirmer_role_is_not_hardcoded_in_domain_contract():
    confirmation = _confirmation(
        MovementConfirmationStatus.PENDIENTE,
        requested_confirmer_membership_id="MEM-POLICY-RESOLVED",
    )
    validate_movement_confirmation(confirmation)
    assert not hasattr(confirmation, "required_role")
